-- NBA insight nuggets (the "bookie killer" output).
--
-- One row per insight: a human-readable nugget with a quantitative confidence
-- score, the teams/players involved, and the underlying correlation that
-- produced it. Generated by backend/nba_insights.py from the correlation
-- tables. Designed to be fast to crawl and return (indexed by game, team, and
-- confidence).
--
-- insight_kind: 'GOOD_VS_BAD_TEAM' | 'MOMENTUM_SWING' | 'BLOWOUT_RISK' |
--               'PLAYER_PROP_EDGE' | 'PLAYER_HEAT' | 'TURNOVER_DIFFERENTIAL' |
--               'FIRST_QUARTER_DEFENSE' | 'THREE_POINT_SWING'
-- confidence: 0-1 (>= 0.70 = 'high confidence' tier)

CREATE TABLE IF NOT EXISTS gold.nba_insight_nugget (
    season          INTEGER NOT NULL,
    game_id         VARCHAR NOT NULL,
    insight_kind    VARCHAR NOT NULL,
    title           VARCHAR NOT NULL,
    body            VARCHAR NOT NULL,          -- human-readable nugget text
    confidence      DOUBLE NOT NULL,           -- 0-1
    teams           VARCHAR,                   -- comma-separated team abbreviations involved
    players         VARCHAR,                   -- comma-separated player names involved
    edge_value      DOUBLE,                    -- the raw edge number behind the nugget
    edge_label      VARCHAR,                   -- human label for the edge (e.g. '+12.3 PPG')
    source_table    VARCHAR,                   -- which correlation table produced it
    source_row_id   VARCHAR,                   -- key into the source table
    created_at      VARCHAR NOT NULL,          -- ISO timestamp
    PRIMARY KEY (season, game_id, insight_kind, title)
);

CREATE INDEX IF NOT EXISTS idx_nba_insight_game
    ON gold.nba_insight_nugget (season, game_id);
CREATE INDEX IF NOT EXISTS idx_nba_insight_confidence
    ON gold.nba_insight_nugget (confidence DESC);
CREATE INDEX IF NOT EXISTS idx_nba_insight_kind
    ON gold.nba_insight_nugget (insight_kind);

-- Curated "top nuggets" per game: the single best insight to display prominently.
-- One row per game (the highest-confidence insight).
CREATE TABLE IF NOT EXISTS gold.nba_game_top_nugget (
    season          INTEGER NOT NULL,
    game_id         VARCHAR NOT NULL,
    insight_kind    VARCHAR NOT NULL,
    title           VARCHAR NOT NULL,
    body            VARCHAR NOT NULL,
    confidence      DOUBLE NOT NULL,
    edge_value      DOUBLE,
    edge_label      VARCHAR,
    PRIMARY KEY (season, game_id)
);
